\label{def:twistBD}



(Paper Eq.~(9.15).) For $(\eps^+, \eps^-) \in \mathbb{Z}^2$ (in practice $\{\pm 1\}^2$),
acts only on odd-length rows ($\ell = i + 1$ odd, $i$ even):
\[
  \mathrm{twistBDRow}(i,\ \eps^+, \eps^-)(p, q) :=
  \begin{cases}
    (p, q) & \ell\text{ even} \\
    (\eps^{+\,h + 1} \eps^{-\,h}\, p,\ \eps^{-\,h + 1} \eps^{+\,h}\, q) & \ell\text{ odd, } h = i / 2.
  \end{cases}
\]
Common cases:
\begin{itemize}
  \item $(1, -1)$: sign twist $\otimes 1^{+-}$ (B/D post-twist when $\eps_\tau = 1$).
  \item $(-1, -1)$: det twist (C/M pre-twist when $\eps_\wp = 1$).
  \item $(1, 1)$: identity.
\end{itemize}

\label{def:charTwistCM}



(Paper Eq.~(9.16)--(9.17).) For $j \in \mathbb{Z}$, $T^j$ negates the pair at row index $i$ iff $j$ is odd and $(i + 1) \bmod 4 = 2$:
\[
  \mathrm{charTwistCMRow}(j, i)(p, q) :=
  \begin{cases}
    (-p, -q) & j\text{ odd and } (i + 1) \bmod 4 = 2 \\
    (p, q) & \text{otherwise}
  \end{cases}
\]

\[
    \mathrm{charTwistCMRow}(j, i)(p, q) :=
    \begin{cases}
      (-p, -q) & j\text{ odd and } (i + 1) \bmod 4 = 2 \\
      (p, q) & \text{otherwise}
    \end{cases}
  \]

\label{def:augment}



$\mathrm{augment}((p_0, q_0), \mathcal{E}) := (p_0, q_0) :: \mathcal{E}$.
Prepend at position~0 (shift existing rows up by~1).

\label{def:thetaLift}



Four variants (paper Eq.~(9.29)--(9.30)):
\begin{itemize}
  \item $\hat\vartheta_{CD} : \MYD_C \to \MYD_D$ (single branch): $\mathcal{E} \mapsto T^j(\mathrm{augment}((p, q), \mathcal{E}))$.
  \item $\hat\vartheta_{DC} : \MYD_D \to \MYD_C$ (two branches: standard with $\mathrm{augment}((n, n), \mathcal{E})$; split with $\mathrm{augment}((-1, -1), \Lambda(\mathcal{E}))$).
  \item $\hat\vartheta_{BM}, \hat\vartheta_{MB}$ analogous.
\end{itemize}

\label{thm:thetaLift_fcSign}



$\mathrm{fcSign}(\hat\vartheta(\mathcal{E})) = (p - \Sign(\mathcal{E}).1,\ q - \Sign(\mathcal{E}).2)$
(the key \emph{firstColSign invariant}).

\label{def:AC_base}



When $|\check{\mathcal{O}}| = 0$ the base $\mathcal{L}_\tau$ is determined by $\gamma$:
\[
  \mathrm{AC.base}\,\gamma = \begin{cases}
    [(1,\ [(1, 0)])] & \gamma = B^+ \\
    [(1,\ [(0, -1)])] & \gamma = B^- \\
    [(1,\ [])] & \gamma \in \{C, D, M\}.
  \end{cases}
\]
(Each list entry is an \texttt{ACResult} branch: \texttt{(coeff, ILS)}.)

\label{def:AC_step}



Given a source $\mathrm{ACResult}$ and target $\gamma$, together with parameters
$(p, q, \eps_\tau, \eps_\wp) \in \mathbb{Z}^2 \times \{0, 1\}^2$, define:
\begin{itemize}
  \item If $\gamma \in \{D, B^+, B^-\}$ (no C/M pre-twist):
  \[
    \mathrm{AC.step} =
    \begin{cases}
      (\mathrm{source.thetaLift}\,\gamma\,p\,q)\otimes(1, -1) & \eps_\tau = 1 \\
      \mathrm{source.thetaLift}\,\gamma\,p\,q & \eps_\tau = 0
    \end{cases}
  \]
  \item If $\gamma \in \{C, M\}$: first pre-twist the source by $\otimes(-1, -1)^{\eps_\wp}$, then theta lift.
\end{itemize}
The resulting \texttt{ACResult} carries all branches.

\label{thm:AC_step_sign_D}



Every branch of the output has $\Sign = (p, q)$:
\[ \forall r \in \mathrm{AC.step}_{D}(\mathrm{source}, p, q, \eps_\tau, \eps_\wp),\quad \Sign(r.2) = (p, q). \]

\label{thm:AC_step_fcSign}



For each $\gamma \in \{D, B^+, B^-, C, M\}$, every branch of $\mathrm{AC.step}$'s output has
$\mathrm{fcSign}(r.2) = (p - \mathrm{prev\_sig}.1,\ q - \mathrm{prev\_sig}.2)$ where $\mathrm{prev\_sig} = \Sign(\text{source})$.

\label{def:tailSymbol}



For D type, the tail is the sequence of cells
$(\mathcal{Q}.\mathrm{colLen}(0), 0),\ (\mathcal{Q}.\mathrm{colLen}(0) + 1, 0),\ \ldots,\ (\mathcal{P}.\mathrm{colLen}(0) - 1, 0)$
in $\mathcal{P}$'s column~0. We write:
\begin{itemize}
  \item $x_\tau := \mathcal{P}_\tau(\mathcal{P}.\mathrm{colLen}(0) - 1, 0)$ — \emph{bottom} tail cell (maximum $\mathrm{layerOrd}$ by layer monotonicity).
  \item $x_1 := \mathcal{P}_\tau(\mathcal{Q}.\mathrm{colLen}(0), 0)$ — \emph{top} tail cell (minimum $\mathrm{layerOrd}$).
\end{itemize}
For B type: analogous symbols in $\mathcal{Q}$.

\label{def:tailSignature}



\[ \mathrm{tailSig}(\tau) := \sum_{i = \tau.\mathcal{Q}.\mathrm{colLen}(0)}^{\tau.\mathcal{P}.\mathrm{colLen}(0) - 1} \mathrm{tailContrib}(\mathcal{P}_\tau(i, 0)). \]
Each cell contributes $\mathrm{tailContrib}$ (Def.~\ref{def:tailContrib}); components sum to~$2$ per cell.

\label{lem:11_3}



Assume $\mathcal{P}.\mathrm{colLen}(0) > \mathcal{Q}.\mathrm{colLen}(0)$. Then:
